import { useRef, useState } from 'react'
import {
  getSysNewspaperList,
  addSysNewspaper,
  editSysNewspaper,
  deleteSysNewspaper,
  updateSysNewspaperStatus,
  SystemConfigTypes
} from '@/apis/admin/system-config'
import ExcelTable from '@/components/exportExcel'
import { ActionType, ProColumns, ModalForm, ProFormText, ProFormDigit, ProFormSelect } from '@ant-design/pro-components'
import {
  Button,
  Popconfirm,
  message,
  Tag,
  Space,
  Tooltip
} from 'antd'
import {
  PlusOutlined,
  EditOutlined,
  DeleteOutlined,
  CheckCircleOutlined,
  StopOutlined,
  ReadOutlined,
  FileTextOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'

// 状态映射
const statusMap: Record<number, { text: string; color: string }> = {
  1: { text: '启用', color: 'success' },
  2: { text: '禁用', color: 'default' },
}

// 投递频率映射
const deliveryFreqMap: Record<string, { text: string; color: string }> = {
  '日刊': { text: '日刊', color: 'blue' },
  '周刊': { text: '周刊', color: 'orange' },
  '月刊': { text: '月刊', color: 'purple' },
}

const Newspaper: React.FC = () => {
  const actionRef = useRef<ActionType>()
  const [modalVisible, setModalVisible] = useState(false)
  const [modalTitle, setModalTitle] = useState('添加报纸类型')
  const [editingRecord, setEditingRecord] = useState<SystemConfigTypes.SysNewspaperListDto | null>(null)
  const [formSubmitting, setFormSubmitting] = useState(false)

  // 打开新增弹窗
  const handleAdd = () => {
    setEditingRecord(null)
    setModalTitle('添加报纸类型')
    setModalVisible(true)
  }

  // 打开编辑弹窗
  const handleEdit = (record: SystemConfigTypes.SysNewspaperListDto) => {
    setEditingRecord(record)
    setModalTitle('编辑报纸类型')
    setModalVisible(true)
  }

  // 保存报纸类型
  const handleSave = async (values: any) => {
    setFormSubmitting(true)
    try {
      const submitData = {
        name: values.name,
        sort: values.sort,
        status: values.status,
        remark: values.remark || '',
        code: values.code,
        deliveryFreq: values.deliveryFreq
      }

      if (editingRecord) {
        // 编辑
        const res = await editSysNewspaper(editingRecord.id, {
          id: editingRecord.id,
          ...submitData
        })
        if (res.code === ResultEnum.SUCCESS) {
          message.success('保存成功')
          setModalVisible(false)
          actionRef.current?.reload()
        } else {
          message.error('保存失败')
        }
      } else {
        // 新增
        const res = await addSysNewspaper(submitData)
        if (res.code === ResultEnum.SUCCESS) {
          message.success('新增成功')
          setModalVisible(false)
          actionRef.current?.reload()
        } else {
          message.error('新增失败')
        }
      }
    } catch (e) {
      console.error('保存报纸类型失败:', e)
      message.error('操作失败')
    } finally {
      setFormSubmitting(false)
    }
  }

  // 更新状态
  const handleUpdateStatus = async (record: SystemConfigTypes.SysNewspaperListDto, newStatus: number) => {
    try {
      // 如果有订阅用户且要禁用，给出提示
      if (newStatus === 2 && record.linkedDevice > 0) {
        message.warning(`该报纸类型已有 ${record.linkedDevice} 个设备订阅，禁用后将不可订阅`)
      }

      const res = await updateSysNewspaperStatus(record.id, { id: record.id })
      if (res.code === ResultEnum.SUCCESS) {
        message.success(newStatus === 1 ? '启用成功' : '禁用成功')
        actionRef.current?.reload()
      } else {
        message.error('操作失败')
      }
    } catch (e) {
      console.error('更新状态失败:', e)
      message.error('操作失败')
    }
  }

  // 删除报纸类型
  const handleDelete = async (record: SystemConfigTypes.SysNewspaperListDto) => {
    try {
      const res = await deleteSysNewspaper(record.id, { id: record.id })
      if (res.code === ResultEnum.SUCCESS) {
        message.success('删除成功')
        actionRef.current?.reload()
      } else {
        message.error('删除失败')
      }
    } catch (e) {
      console.error('删除报纸类型失败:', e)
      message.error('操作失败')
    }
  }

  // 表格列定义
  const columns: ProColumns<SystemConfigTypes.SysNewspaperListDto>[] = [
    {
      title: '类型ID',
      dataIndex: 'id',
      key: 'id',
      width: 100,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>
          {text}
        </span>
      ),
    },
    {
      title: '报纸名称',
      dataIndex: 'name',
      key: 'name',
      width: 160,
      render: (text) => (
        <Space>
          <FileTextOutlined style={{ color: '#1890ff' }} />
          <span>{text}</span>
        </Space>
      ),
    },
    {
      title: '报纸编码',
      dataIndex: 'code',
      key: 'code',
      width: 140,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>{text}</span>
      ),
    },
    {
      title: '投递频率',
      dataIndex: 'deliveryFreq',
      key: 'deliveryFreq',
      width: 100,
      hideInSearch: true,
      render: (text) => {
        const freq = deliveryFreqMap[text as string]
        return <Tag color={freq?.color || 'default'}>{freq?.text || text}</Tag>
      },
    },
    {
      title: '排序值',
      dataIndex: 'sort',
      key: 'sort',
      width: 100,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>{text}</span>
      ),
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 100,
      valueType: 'select',
      valueEnum: {
        1: { text: '启用', status: 'Success' },
        2: { text: '禁用', status: 'Default' },
      },
      render: (_, record) => {
        const status = statusMap[record.status]
        return <Tag color={status?.color || 'default'}>{status?.text || '未知'}</Tag>
      },
    },
    {
      title: '订阅用户数',
      dataIndex: 'linkedDevice',
      key: 'linkedDevice',
      width: 120,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>{text || 0}</span>
      ),
    },
    {
      title: '创建时间',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 160,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontSize: 13, color: '#666' }}>{text}</span>
      ),
    },
    {
      title: '操作',
      key: 'option',
      valueType: 'option',
      fixed: 'right',
      width: 140,
      render: (_, record) => [
        <Tooltip title="编辑" key={`${record.id}-edit`}>
          <Button
            type="link"
            title="编辑"
            icon={<EditOutlined />}
            onClick={() => handleEdit(record)}
          />
        </Tooltip>,
        record.status === 1 ? (
          <Tooltip title="禁用" key={`${record.id}-disable`}>
            <Popconfirm
              title="确定要禁用该报纸类型吗？"
              description={record.linkedDevice > 0 ? `该报纸类型已有 ${record.linkedDevice} 个设备订阅，禁用后将不可订阅` : undefined}
              onConfirm={() => handleUpdateStatus(record, 2)}
              okText="确定"
              cancelText="取消"
            >
              <Button type="link" danger title="禁用" icon={<StopOutlined />} />
            </Popconfirm>
          </Tooltip>
        ) : (
          <Tooltip title="启用" key={`${record.id}-enable`}>
            <Button
              type="link"
              title="启用"
              icon={<CheckCircleOutlined />}
              style={{ color: '#52c41a' }}
              onClick={() => handleUpdateStatus(record, 1)}
            />
          </Tooltip>
        ),
        <Tooltip title="删除" key={`${record.id}-delete`}>
          <Popconfirm
            title="确定要删除该报纸类型吗？"
            description={record.linkedDevice > 0 ? '该报纸类型已被用户订阅，无法直接删除，请先禁用' : '删除后不可恢复'}
            onConfirm={() => handleDelete(record)}
            okText="确定"
            cancelText="取消"
            disabled={record.linkedDevice > 0}
          >
            <Button
              type="link"
              danger
              title="删除"
              icon={<DeleteOutlined />}
              disabled={record.linkedDevice > 0}
            />
          </Popconfirm>
        </Tooltip>,
      ],
    },
  ]

  return (
    <>
      <ExcelTable
        key="newspaper-list"
        columns={columns}
        requestFn={async () => {
          return await getSysNewspaperList()
        }}
        actionRef={actionRef}
        rowSelection={false}
        options={{
          fullScreen: false,
          reload: true,
          setting: false,
          density: false
        }}
        search={false}
        toolBarRenderFn={() => [
          <Button
            key="add"
            type="primary"
            icon={<PlusOutlined />}
            onClick={handleAdd}
          >
            添加报纸类型
          </Button>,
        ]}
        scroll={{ x: 1100 }}
      />

      {/* 新增/编辑弹窗 */}
      <ModalForm
        title={
          <Space>
            <ReadOutlined style={{ color: '#1890ff' }} />
            {modalTitle}
          </Space>
        }
        open={modalVisible}
        onOpenChange={setModalVisible}
        onFinish={handleSave}
        initialValues={editingRecord ? {
          name: editingRecord.name,
          code: editingRecord.code,
          deliveryFreq: editingRecord.deliveryFreq,
          sort: editingRecord.sort,
          status: editingRecord.status
        } : {
          status: 1,
        }}
        submitter={{
          submitButtonProps: {
            loading: formSubmitting,
          },
        }}
        layout="horizontal"
        labelCol={{ flex: '0 0 100px' }}
        wrapperCol={{ flex: '1 1 auto' }}
        width={560}
      >
        <ProFormText
          name="name"
          label="报纸名称"
          placeholder="例如：人民日报"
          rules={[{ required: true, message: '请输入报纸名称' }]}
        />
        <ProFormText
          name="code"
          label="报纸编码"
          placeholder="例如：RENMIN_DAILY"
          disabled={!!editingRecord}
          rules={[{ required: true, message: '请输入报纸编码' }]}
        />
        <ProFormSelect
          name="deliveryFreq"
          label="投递频率"
          options={[
            { label: '日刊', value: '日刊' },
            { label: '周刊', value: '周刊' },
            { label: '月刊', value: '月刊' },
          ]}
          rules={[{ required: true, message: '请选择投递频率' }]}
        />
        <ProFormDigit
          name="sort"
          label="排序值"
          min={0}
          fieldProps={{ style: { width: 200 } }}
          rules={[{ required: true, message: '请输入排序值' }]}
        />
        <ProFormSelect
          name="status"
          label="状态"
          options={[
            { label: '启用', value: 1 },
            { label: '禁用', value: 2 },
          ]}
          rules={[{ required: true, message: '请选择状态' }]}
        />
        <ProFormText
          name="remark"
          label="备注"
          placeholder="可选"
        />
      </ModalForm>
    </>
  )
}

export default Newspaper